css:
button {
  transform-style: preserve-3d;
  padding: 10px 20px;
  background-color: white;
  color: black;
  border: none;
  border-radius: 4px;
  cursor: pointer;
  transform: rotateX(20deg);
  transition: all 0.5s;
  position: relative;
  overflow: hidden;
  font-weight: bolder;
}

button:hover {
  color: white;
  z-index: 1s;
}

button::before {
  content: "";
  position: absolute;
  width: 0%;
  height: 100%;
  background-color: lightcoral;
  top: 0;
  left: -40px;
  z-index: -1;
  transform: skewX(45deg);
  border-radius: 4px;
  transition: all 1s;
}

button::after {
  content: "";
  position: absolute;
  width: 10%;
  filter: blur(7px);
  height: 100%;
  background-color: white;
  top: 0;
  left: -10px;
  transition: all 0.9s linear;
  transform: skewX(45deg);
}

button:hover::after {
  transform: translateX(115px);
}

button:hover::before {
  width: 200%;
}
